/**
 * Unit tests for lib/motionNpz.ts — the Motion Card's client-side motion
 * engine. The module powers the live stage (load/precompute/b64), the
 * VNCCS export pair (soma77ToCoco18 + AZIMUTH_PRESETS), and the chain
 * write path (writeNpz + patchFrame). Each surface test mocks this module
 * away, so the real math had zero runtime coverage — these tests pin:
 *
 *   1. writeNpz → parseNpz round-trip (shapes, values, CRC — the writer
 *      must produce NPZ files numpy can load: 64-byte-aligned NPY v1
 *      headers + real CRC32s).
 *   2. soma77ToCoco18 vs a fixture generated by the REAL
 *      custom_nodes/melite-poser-nodes/library/soma_to_coco.py (the DWPose /
 *      vnccs contract — subject's right = image LEFT, ear extrapolation).
 *   3. AZIMUTH_PRESETS convention — 0 = front (+Z camera), 90 = right
 *      (+X) — the Blender convention the vnccs flow's angle names use.
 *   4. patchFrame rotation reconstruction — an edited child direction is
 *      arc-aligned along the SOMA-77 hierarchy.
 *   5. vertsToB64 round-trip (cm scaling).
 *
 * parseNpz uses DecompressionStream — available in Node 18+ (vitest's
 * worker runtime), no polyfill needed.
 */
import { describe, it, expect } from "vitest"
import * as THREE from "three"
import { parseNpz } from "@melite/formats"
import {
  writeNpz, npzToDataUrl, soma77ToCoco18, AZIMUTH_PRESETS,
  azimuthCameraPos, stepAzimuth, vertsToB64, patchFrame,
} from "@melite/formats"
import { deformFrame, type SomaSkin } from "@melite/formats"

const J = 77

/** Small synthetic motion: T=3 frames, plausible SOMA-77 values (meters). */
function makeMotion(T = 3) {
  const posed = new Float32Array(T * J * 3)
  const rots = new Float32Array(T * J * 9)
  for (let f = 0; f < T; f++) {
    for (let j = 0; j < J; j++) {
      const jb = (f * J + j) * 3
      posed[jb] = j * 0.01 + f * 0.1 // x drifts per frame
      posed[jb + 1] = 0.05 + j * 0.02
      posed[jb + 2] = 0.0
      const rb = (f * J + j) * 9
      rots[rb] = 1 // identity rotation
      rots[rb + 4] = 1
      rots[rb + 8] = 1
    }
  }
  return { posed, rots }
}

describe("writeNpz → parseNpz round-trip", () => {
  it.each([true, false])("round-trips shapes + values (compress=%s)", async (compress) => {
    const { posed, rots } = makeMotion()
    const fps = new Float32Array([30])
    const bytes = await writeNpz(
      {
        posed_joints: { data: posed, shape: [3, J, 3] },
        global_rot_mats: { data: rots, shape: [3, J, 3, 3] },
        fps: { data: fps },
      },
      compress,
    )
    expect(bytes.byteLength).toBeGreaterThan(0)

    const arrays = await parseNpz(bytes)
    // The exact key set — numpy would refuse unknown entries.
    expect([...arrays.keys()].sort()).toEqual(
      ["fps", "global_rot_mats", "posed_joints"].sort(),
    )

    const j = arrays.get("posed_joints")!
    expect(j.shape).toEqual([3, J, 3])
    expect(j.data).toHaveLength(3 * J * 3)
    const jd = j.data as Float32Array
    expect(jd[0]).toBeCloseTo(0, 6)
    expect(jd[1]).toBeCloseTo(0.05, 6)
    expect(jd[J * 3]).toBeCloseTo(0.1, 6) // frame 1 joint 0 x drift

    const r = arrays.get("global_rot_mats")!
    expect(r.shape).toEqual([3, J, 3, 3])
    const rd = r.data as Float32Array
    expect(rd[0]).toBeCloseTo(1, 6) // identity
    expect(rd[4]).toBeCloseTo(1, 6)
    expect(rd[8]).toBeCloseTo(1, 6)

    const f = arrays.get("fps")!
    expect(f.shape).toEqual([1])
    expect((f.data as Float32Array)[0]).toBeCloseTo(30, 6)
  })

  it("produces a data URL in the _upload_input_images shape", async () => {
    const { posed, rots } = makeMotion(1)
    const bytes = await writeNpz({
      posed_joints: { data: posed, shape: [1, J, 3] },
      global_rot_mats: { data: rots, shape: [1, J, 3, 3] },
      fps: { data: new Float32Array([30]) },
    })
    const url = npzToDataUrl(bytes)
    expect(url.startsWith("data:application/octet-stream;base64,")).toBe(true)
    // Decode back — must be byte-identical (the chain slot uploads it).
    const b64 = url.split(",")[1]
    const bin = atob(b64)
    const round = new Uint8Array(bin.length)
    for (let i = 0; i < bin.length; i++) round[i] = bin.charCodeAt(i)
    expect(round).toEqual(bytes)
  })
})

